/** Source: contest_util.c → Task_FlashStarsAndHearts */
export const Task_FlashStarsAndHearts: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  if (++task.data[0] == 2)
      {
          task.data[0] = 0;
          if (!task.data[2])
              task.data[1]++;
          else
              task.data[1]--;

          if (task.data[1] == 16)
              task.data[2] = true;
          else if (task.data[1] == 0)
              task.data[2] = false;

          BlendPalette(BG_PLTT_ID(6) + 11, 1, task.data[1], RGB(30, 22, 11));
          BlendPalette(BG_PLTT_ID(6) + 8, 1, task.data[1], RGB_WHITE);
          BlendPalette(BG_PLTT_ID(6) + 14, 1, task.data[1], RGB(30, 29, 29));
      }

      if (task.data[1] == 0)
          sContestResults.data.pointsFlashing = false;
      else
          sContestResults.data.pointsFlashing = true;
};

