/** Source: contest_util.c → Task_ShowContestEntryMonPic */
export const Task_ShowContestEntryMonPic: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let task: any = _gt(rt, taskId);
      let sprite: any = null;

      switch(task.data[0])
      {
      case 0:
          task.data[0]++;
          break;
      case 1:
          task.data[5] = CreateWindowFromRect(10, 3, 8, 8);
          SetStandardWindowBorderStyle(task.data[5], true);
          task.data[0]++;
          break;
      case 2:
          break;
      case 3:
          sprite = _gs(rt, task.data[2]);
          FreeSpritePaletteByTag(GetSpritePaletteTagByPaletteNum(rt.gba.oam[sprite.oamIndex].paletteBank));

          if(rt.gba.oam[sprite.oamIndex].affineMode)
              FreeOamMatrix(rt.gba.oam[sprite.oamIndex].affineParamIndex);

          rt.DestroySprite(sprite.spriteId);
          task.data[0]++;
          break;
      case 4:
          ClearToTransparentAndRemoveWindow(task.data[5]);
          rt.DestroyTask(taskId);
          break;
      }
};

/** Source: contest_util.c → Task_LinkContestWaitForConnection */
export const Task_LinkContestWaitForConnection: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  switch (task.data[0])
      {
      case 0:
          if (IsLinkTaskFinished())
          {
              SetLinkStandbyCallback();
              task.data[0]++;
          }
          break;
      case 1:
          task.data[0]++;
          break;
      default:
          if (IsLinkTaskFinished() == 1)
          {
              ScriptContext_Enable();
              rt.DestroyTask(taskId);
          }
          break;
      }
};

